16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * The owner's unified member id, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
20	 * canonical region (see {@link RegionResolver}), the two-digit fiscal year (see
21	 * {@link FiscalYear}), the eight upper-case hexadecimal HASH8 of the region-and-hash
22	 * identity, and a single Luhn check digit (see {@link LuhnCheckDigit}) computed over the
23	 * digits of the preceding {@code <REGION><FY><HASH8>}.
24	 *
25	 * <p>Single source of truth for the member-id format, so callers build and read its
26	 * segments the same way and never repeat the layout. The region is a run of letters and
27	 * the fiscal year the two digits immediately after it, so the leading segments can be
28	 * read back even when a collision suffix is appended to the id.
29	 */
30	public final class MemberId {
31	
32	    private MemberId() {
33	    }
34	
35	    /**
36	     * Build a member id from its parts: the {@code <REGION><FY><HASH8>} body followed by
37	     * the Luhn check digit computed over that body's digits.
38	     *
39	     * @param region          the owner's canonical region
40	     * @param fiscalYearShort the two-digit fiscal year
41	     * @param hash8           the eight upper-case hex characters of the region-and-hash identity
42	     * @return the formatted member id, e.g. {@code "NSW261A2B3C4D5"}
43	     */
44	    public static String format(String region, int fiscalYearShort, String hash8) {
45	        String body = region + String.format("%02d", fiscalYearShort) + hash8;
46	        return body + LuhnCheckDigit.of(body);
47	    }
48	
49	    /**
50	     * The region segment of a member id: its leading run of letters, which ends where the
51	     * two-digit fiscal year begins.
52	     */
53	    public static String regionOf(String memberId) {
54	        int end = 0;
55	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
56	            end++;
57	        }
58	        return memberId.substring(0, end);
59	    }
60	
61	    /**
62	     * The two-digit fiscal-year segment of a member id: the two digits immediately
63	     * following its {@link #regionOf(String) region}.
64	     */
65	    public static int fiscalYearShortOf(String memberId) {
66	        int start = regionOf(memberId).length();
67	        return Integer.parseInt(memberId.substring(start, start + 2));
68	    }
69	}
