28	import java.time.LocalDate;
29	import java.util.Collection;
30	import java.util.Comparator;
31	import java.util.List;
32	import java.util.Optional;
33	import java.util.Set;
34	import java.util.function.Supplier;
35	
36	/**
37	 * Mostly used as a facade for all Petclinic controllers
38	 * Also a placeholder for @Transactional and @Cacheable annotations
39	 *
40	 * @author Michael Isvy
41	 * @author Vitaliy Fedoriv
42	 */
43	@Service
44	public class ClinicServiceImpl implements ClinicService {
45	
46	    /**
47	     * Number of owners that must already carry a day's registration date before a
48	     * further owner registered that day is flagged with a bulk signup warning.
49	     */
50	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
51	
52	    /**
53	     * Number of owners a city must already hold before a further owner registered in it
54	     * is flagged with a capacity warning, signalling the city is approaching (but has not
55	     * yet reached) the hard per-city capacity limit enforced by the create endpoint.
56	     */
57	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40;
58	
59	    private final PetRepository petRepository;
60	    private final VetRepository vetRepository;
61	    private final OwnerRepository ownerRepository;
62	    private final VisitRepository visitRepository;
63	    private final SpecialtyRepository specialtyRepository;
64	    private final PetTypeRepository petTypeRepository;
65	    private final MemberIdGenerator memberIdGenerator;
66	    private final HouseholdIdGenerator householdIdGenerator;
67	
68	    public ClinicServiceImpl(
69	        PetRepository petRepository,
70	        VetRepository vetRepository,
71	        OwnerRepository ownerRepository,
72	        VisitRepository visitRepository,
73	        SpecialtyRepository specialtyRepository,
74	        PetTypeRepository petTypeRepository,
75	        MemberIdGenerator memberIdGenerator,
76	        HouseholdIdGenerator householdIdGenerator) {
77	        this.petRepository = petRepository;
78	        this.vetRepository = vetRepository;
79	        this.ownerRepository = ownerRepository;
80	        this.visitRepository = visitRepository;
81	        this.specialtyRepository = specialtyRepository;
82	        this.petTypeRepository = petTypeRepository;
83	        this.memberIdGenerator = memberIdGenerator;
84	        this.householdIdGenerator = householdIdGenerator;
85	    }
86	
87	    @Override
88	    @Transactional(readOnly = true)
89	    public Collection<Pet> findAllPets() throws DataAccessException {
90	        return petRepository.findAll();
91	    }
92	
93	    @Override
94	    @Transactional(readOnly = true)
95	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
96	        return petRepository.findAll(pageable);
97	    }
98	
99	    @Override
100	    @Transactional
101	    public void deletePet(Pet pet) throws DataAccessException {
102	        petRepository.delete(pet);
103	    }
104	
105	    @Override
106	    @Transactional(readOnly = true)
107	    public Visit findVisitById(int visitId) throws DataAccessException {
108	        return findEntityById(() -> visitRepository.findById(visitId));
109	    }
110	
111	    @Override
112	    @Transactional(readOnly = true)
113	    public Collection<Visit> findAllVisits() throws DataAccessException {
114	        return visitRepository.findAll();
115	    }
116	
117	    @Override
118	    @Transactional
119	    public void deleteVisit(Visit visit) throws DataAccessException {
120	        visitRepository.delete(visit);
121	    }
122	
123	    @Override
124	    @Transactional(readOnly = true)
125	    public Vet findVetById(int id) throws DataAccessException {
126	        return findEntityById(() -> vetRepository.findById(id));
127	    }
128	
129	    @Override
130	    @Transactional(readOnly = true)
131	    public Collection<Vet> findAllVets() throws DataAccessException {
132	        return vetRepository.findAll();
133	    }
134	
135	    @Override
136	    @Transactional
137	    public void saveVet(Vet vet) throws DataAccessException {
138	        vetRepository.save(vet);
139	    }
140	
141	    @Override
142	    @Transactional
143	    public void deleteVet(Vet vet) throws DataAccessException {
144	        vetRepository.delete(vet);
145	    }
146	
147	    @Override
148	    @Transactional(readOnly = true)
149	    public Collection<Owner> findAllOwners() throws DataAccessException {
150	        return ownerRepository.findAll();
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
156	        if (lastName != null) {
157	            return ownerRepository.findByLastName(lastName, pageable);
158	        }
159	        return ownerRepository.findAll(pageable);
160	    }
161	
162	    @Override
163	    @Transactional
164	    public void deleteOwner(Owner owner) throws DataAccessException {
165	        // Soft delete: retain the row and flag it so the owner stays retrievable but is
166	        // ignored by the create endpoint's duplicate/identity checks.
167	        owner.setDeleted(true);
168	        ownerRepository.save(owner);
169	    }
170	
171	    @Override
172	    @Transactional(readOnly = true)
173	    public PetType findPetTypeById(int petTypeId) {
174	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
175	    }
176	
177	    @Override
178	    @Transactional(readOnly = true)
179	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
180	        return petTypeRepository.findAll();
181	    }
182	
183	    @Override
184	    @Transactional
185	    public void savePetType(PetType petType) throws DataAccessException {
186	        petTypeRepository.save(petType);
187	    }
188	
189	    @Override
190	    @Transactional
191	    public void deletePetType(PetType petType) throws DataAccessException {
192	        petTypeRepository.delete(petType);
193	    }
194	
195	    @Override
196	    @Transactional(readOnly = true)
197	    public Specialty findSpecialtyById(int specialtyId) {
198	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
199	    }
200	
201	    @Override
202	    @Transactional(readOnly = true)
203	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
204	        return specialtyRepository.findAll();
205	    }
206	
207	    @Override
208	    @Transactional
209	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
210	        specialtyRepository.save(specialty);
211	    }
212	
213	    @Override
214	    @Transactional
215	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
216	        specialtyRepository.delete(specialty);
217	    }
218	
219	    @Override
220	    @Transactional(readOnly = true)
221	    public Collection<PetType> findPetTypes() throws DataAccessException {
222	        return petRepository.findPetTypes();
223	    }
224	
225	    @Override
226	    @Transactional(readOnly = true)
227	    public Owner findOwnerById(int id) throws DataAccessException {
228	        return findEntityById(() -> ownerRepository.findById(id));
229	    }
230	
231	    @Override
232	    @Transactional(readOnly = true)
233	    public Pet findPetById(int id) throws DataAccessException {
234	        return findEntityById(() -> petRepository.findById(id));
235	    }
236	
237	    @Override
238	    @Transactional
239	    public void savePet(Pet pet) throws DataAccessException {
240	        pet.setType(findPetTypeById(pet.getType().getId()));
241	        petRepository.save(pet);
242	    }
243	
244	    @Override
245	    @Transactional
246	    public void saveVisit(Visit visit) throws DataAccessException {
247	        visitRepository.save(visit);
248	
249	    }
250	
251	    @Override
252	    @Transactional(readOnly = true)
253	    public Collection<Vet> findVets() throws DataAccessException {
254	        return vetRepository.findAll();
255	    }
256	
257	    @Override
258	    @Transactional
259	    public void saveOwner(Owner owner) throws DataAccessException {
260	        if (owner.isNew()) {
261	            if (owner.getMemberId() == null) {
262	                LocalDate registrationDate = BusinessDay.rollForward(
263	                    owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
264	                owner.setMemberId(memberIdGenerator.generateUnique(
265	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
266	                    FiscalYear.shortYearOf(registrationDate),
267	                    owner.getTelephone(), owner.getLastName(),
268	                    ownerRepository::existsByMemberId));
269	            }
270	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
271	            owner.setBulkSignupWarning(
272	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
273	            owner.setCapacityWarning(
274	                ownerRepository.countByCity(owner.getCity()) >= CITY_CAPACITY_WARNING_THRESHOLD);
275	            owner.setHouseholdId(householdIdFor(owner));
276	            owner.setHouseholdSize(householdSizeIncluding(owner));
277	            owner.setMembershipLevelCap(membershipLevelCapFor(owner));
278	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
279	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
280	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
281	        }
282	        ownerRepository.save(owner);
283	
284	    }
285	
286	    /**
287	     * The deterministic, shared household id this owner maps to, derived from its last
288	     * name and postcode so that owners sharing both belong to the same household.
289	     */
290	    private String householdIdFor(Owner owner) {
291	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
292	    }
293	
294	    /**
295	     * Size of the household this new owner will belong to once persisted: the owners
296	     * already sharing its household id, plus the owner itself. An owner with no shared
297	     * household id stands alone, so its household size is one.
298	     */
299	    private int householdSizeIncluding(Owner owner) {
300	        if (owner.getHouseholdId() == null) {
301	            return 1;
302	        }
303	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
304	    }
305	
306	    /**
307	     * Count the existing owners that already share the given first and last name,
308	     * compared case-insensitively. Used to stamp a new owner's namesake count at
309	     * registration, before it is itself persisted.
310	     */
311	    private int countNamesakes(String firstName, String lastName) {
312	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
313	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
314	            .count();
315	    }
316	
317	    /**
318	     * The existing owners that already belong to this owner's household, i.e. the persisted
319	     * owners sharing its computed household id. An owner with no household id (that maps to no
320	     * shared household) has no existing household members. As the household id is derived from
321	     * the last name, the candidates are narrowed by last name before the id is matched.
322	     */
323	    private List<Owner> existingHouseholdMembers(Owner owner) {
324	        String householdId = owner.getHouseholdId();
325	        if (householdId == null) {
326	            return List.of();
327	        }
328	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
329	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
330	            .toList();
331	    }
332	
333	    /**
334	     * The ceiling to stamp on a new owner's membership level: one above the highest membership
335	     * level currently held by an existing member of its household, so the new owner's level
336	     * cannot exceed one above the household maximum. Null when the owner has no existing
337	     * household member, in which case no ceiling applies. See {@link Owner#getMembershipLevel()}.
338	     */
339	    private Integer membershipLevelCapFor(Owner owner) {
340	        return existingHouseholdMembers(owner).stream()
341	            .map(Owner::getMembershipLevel)
342	            .max(Comparator.naturalOrder())
343	            .map(max -> max + 1)
344	            .orElse(null);
345	    }
346	
347	    /**
348	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate of:
349	     * a live owner that is not a hard duplicate (its {@link Owner#getIdentityKey() identity
350	     * key} differs) yet shares the new owner's phonetic last name (see {@link Soundex}) and
351	     * postcode. When several match, the earliest (lowest id) is chosen. An owner with no
352	     * postcode belongs to no such group, and one that deliberately declared it shares a
353	     * household is never a suspected duplicate.
354	     */
355	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
356	        String postcode = owner.getPostcode();
357	        if (owner.isDeclaredHouseholdMember() || postcode == null || postcode.isBlank()) {
358	            return Optional.empty();
359	        }
360	        String identityKey = owner.getIdentityKey();
361	        return liveOwnersSoundingLike(owner).stream()
362	            .filter(existing -> postcode.equals(existing.getPostcode()))
363	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
364	            .min(Comparator.comparing(Owner::getId));
365	    }
366	
367	    /**
368	     * The live (non-deleted) owners whose last name sounds like this owner's, i.e. shares its
369	     * Soundex code. This is the shared candidate set for both hard-duplicate detection and the
370	     * soft match, which group owners by the phonetic sound of the last name (as the identity
371	     * key does) rather than by an exact last-name match.
372	     */
373	    private List<Owner> liveOwnersSoundingLike(Owner owner) {
374	        String soundex = Soundex.of(owner.getLastName());
375	        return ownerRepository.findByDeletedFalse().stream()
376	            .filter(existing -> soundex.equals(Soundex.of(existing.getLastName())))
377	            .toList();
378	    }
379	
380	    @Override
381	    @Transactional(readOnly = true)
382	    public boolean isDuplicateOwner(Owner owner) throws DataAccessException {
383	        String identityKey = owner.getIdentityKey();
384	        return liveOwnersSoundingLike(owner).stream()
385	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
386	    }
387	
388	    @Override
389	    @Transactional(readOnly = true)
390	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
391	        return ownerRepository.findByLastName(lastName);
392	    }
393	
394	    @Override
395	    @Transactional(readOnly = true)
396	    public long countOwnersByCity(String city) throws DataAccessException {
397	        return ownerRepository.countByCity(city);
398	    }
399	
400	    @Override
401	    @Transactional(readOnly = true)
402	    public long countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
403	        return ownerRepository.countByRegistrationDate(registrationDate);
404	    }
405	
406	    @Override
407	    @Transactional(readOnly = true)
408	    public Collection<Visit> findVisitsByPetId(int petId) {
409	        return visitRepository.findByPetId(petId);
410	    }
411	
412	    @Override
413	    @Transactional(readOnly = true)
414	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
415	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
416	    }
417	
418	    private <T> T findEntityById(Supplier<T> supplier) {
419	        try {
420	            return supplier.get();
421	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
422	            // Just ignore not found exceptions for Jdbc/Jpa realization
423	            return null;
424	        }
425	    }
426	
427	}
428

